import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { NavigationComponent } from '../../core/components/navigation.component';
import { FooterComponent } from '../../core/components/footer.component';

@Component({
    selector: 'app-home',
    standalone: true,
    imports: [CommonModule, NavigationComponent, FooterComponent],
    template: `
        <app-navigation></app-navigation>
        <main class="pt-20 pb-10">
            <!-- Hero Section -->
            <section class="h-screen bg-gradient-to-br from-charcoal via-misty-blue to-charcoal flex items-center justify-center">
                <div class="text-center text-white px-6">
                    <h1 class="text-6xl font-bold mb-6">Elitex Beauty Salon</h1>
                    <p class="text-2xl mb-8">Ultra-Luxury Beauty Services</p>
                    <button (click)="scrollToServices()" class="px-8 py-3 bg-soft-gold text-charcoal font-bold rounded-full hover:shadow-lg">
                        Explore Services
                    </button>
                </div>
            </section>

            <!-- Featured Services -->
            <section class="py-20 px-6 max-w-7xl mx-auto">
                <h2 class="text-4xl font-bold text-center mb-12">Our Signature Services</h2>
                <div class="grid md:grid-cols-3 gap-8">
                    <div *ngFor="let service of featuredServices" (click)="navigateToCategory(service.id)"
                         class="cursor-pointer bg-white rounded-lg shadow-lg hover:shadow-xl transition-shadow p-6">
                        <div class="text-4xl mb-4">{{ service.icon }}</div>
                        <h3 class="text-2xl font-bold text-charcoal mb-2">{{ service.name }}</h3>
                        <p class="text-gray-600">{{ service.description }}</p>
                    </div>
                </div>
            </section>

            <!-- CTA Section -->
            <section class="bg-soft-gold py-12 px-6 text-center">
                <h2 class="text-3xl font-bold text-charcoal mb-4">Ready to Pamper Yourself?</h2>
                <button (click)="goToBooking()" class="px-8 py-3 bg-charcoal text-white font-bold rounded-full hover:shadow-lg">
                    Book Your Appointment
                </button>
            </section>
        </main>
        <app-footer></app-footer>
    `
})
export class HomeComponent {
    featuredServices = [
        {
            id: 'hair',
            name: 'Hair Services',
            icon: '✂️',
            description: 'Expert cuts, colors, and styling'
        },
        {
            id: 'nails',
            name: 'Nail Services',
            icon: '💅',
            description: 'Manicures, pedicures, nail art'
        },
        {
            id: 'facial',
            name: 'Facial & Skin Care',
            icon: '✨',
            description: 'Rejuvenating treatments'
        },
        {
            id: 'bridal',
            name: 'Bridal Services',
            icon: '💎',
            description: 'Complete bridal makeovers'
        },
        {
            id: 'waxing',
            name: 'Waxing Services',
            icon: '🌹',
            description: 'Professional waxing treatments'
        },
        {
            id: 'mehandi',
            name: 'Mehandi Art',
            icon: '🎨',
            description: 'Traditional and modern designs'
        }
    ];

    constructor(private router: Router) {}

    navigateToCategory(categoryId: string): void {
        this.router.navigate(['/service-categories'], {
            queryParams: { category: categoryId }
        });
    }

    goToBooking(): void {
        this.router.navigate(['/booking']);
    }

    scrollToServices(): void {
        this.goToBooking();
    }
}
